package mz.bam.seeky.android;
import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=android.app.Application.class,qualifiers="w360dp-h800dp-mdpi",shadows={ReferenceDesign5150Test.LocalStorage.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class Layout5151Test {
 ReferenceDesign5150Test f;MainActivity a;
 @Before public void before()throws Exception{f=new ReferenceDesign5150Test();f.before();a=f.a;}
 @After public void after()throws Exception{f.after();}
 void measure(int w,int h){a.shell.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));a.shell.layout(0,0,w,h);}
 void spinners(View v,List<Spinner> out){if(v instanceof Spinner)out.add((Spinner)v);if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)spinners(g.getChildAt(i),out);}}
 void applyMode(int mode){a.viewDialog();android.app.Dialog dialog=ShadowDialog.getLatestDialog();List<Spinner> choices=new ArrayList<>();spinners(dialog.getWindow().getDecorView(),choices);assertEquals(2,choices.size());choices.get(0).setSelection(mode);((UiDialog)dialog).getButton(-1).performClick();}
 void books(int count)throws Exception{try(StudyStore db=new StudyStore(a)){for(int n=0;n<count;n++)db.save("materials",0,StudyStore.values("subject",0,"title","Livro de ensaio "+n,"author","Autor de ensaio","name","Livro "+n+".txt","mime","text/plain","path","/private/fixture.txt","hash",String.format(java.util.Locale.ROOT,"%064x",n+1),"bytes",100,"progress",n%100,"status","A estudar","created",n+1,"updated",n+1));}a.books.mode=1;a.tab="Livros";a.render();f.drain();}
 int[] position(View v){int[] p=new int[2];v.getLocationOnScreen(p);return p;}
 @Test public void changingExibirReallyChangesAllSixCategoryLayoutsAndKeepsCategoryActions()throws Exception{int[] columns={1,1,2,4,2,4};for(int mode=0;mode<6;mode++){applyMode(mode);assertEquals(mode,a.viewMode);assertEquals(mode,a.prefs.getInt("view_mode",-1));assertEquals(mode,a.homeCategories.mode);assertEquals(columns[mode],a.homeCategories.columns);assertEquals(9,a.homeCategories.cards.size());assertEquals(mode<=1||mode==4?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL,a.homeCategories.cards.get(0).getOrientation());}a.homeCategories.cards.get(0).performClick();assertEquals("Pesquisa",a.tab);assertEquals("PDF",a.category);}
 @Test @Config(qualifiers="w288dp-h640dp-mdpi") public void compactCategoriesKeepNamesCountsAndIconsCentredOnTheSmallPhone()throws Exception{for(int mode:new int[]{3,5}){applyMode(mode);for(int size=0;size<3;size++){a.iconSize=size;IconSizing.set(a,"icon_size",size);a.render();f.drain();measure(288,640);HomeCategories categories=a.homeCategories;for(int i=0;i<9;i++){View card=categories.cards.get(i);TextView title=categories.titles.get(i),count=categories.counts.get(i);assertTrue("Category height "+card.getHeight(),card.getHeight()<=112);assertTrue(card.getWidth()>=(mode==5?56:70));assertEquals(Gravity.CENTER_HORIZONTAL,title.getGravity()&Gravity.HORIZONTAL_GRAVITY_MASK);assertEquals(Gravity.CENTER_HORIZONTAL,count.getGravity()&Gravity.HORIZONTAL_GRAVITY_MASK);View copy=(View)title.getParent();assertTrue(copy.getBottom()<=card.getHeight()-card.getPaddingBottom());assertTrue(count.getBottom()<=copy.getHeight());}}}applyMode(3);f.drain();f.capture(a.shell,"categorias-compactas",288,640);}
 @Test public void libraryHeaderImportAndMenusRemainFixedWhileBooksScroll()throws Exception{books(18);measure(360,800);View header=a.books.header,filter=f.description(header,"Ordenar e filtrar"),search=f.description(header,"Pesquisar livros"),more=f.description(header,"Opções dos livros");assertNotNull(filter);assertNotNull(search);assertNotNull(more);int top=position(header)[1],filterY=position(filter)[1],contentY=position(a.books.content.getChildAt(0))[1];a.books.scroll.scrollTo(0,480);assertEquals(480,a.books.scroll.getScrollY());assertEquals(top,position(header)[1]);assertEquals(filterY,position(filter)[1]);assertTrue(position(a.books.content.getChildAt(0))[1]<contentY);for(View button:new View[]{filter,search,more}){Rect visible=new Rect();assertTrue(button.getGlobalVisibleRect(visible));assertEquals(button.getHeight(),visible.height());assertEquals(button.getWidth(),visible.width());}f.capture(a.shell,"livros-cabecalho-fixo",360,800);}
 @Test @Config(qualifiers="w288dp-h640dp-mdpi") public void bookHeaderFillsBothSidesAndEveryMenuAndTitleFits()throws Exception{books(4);measure(288,640);assertEquals(0,a.shell.getPaddingLeft());assertEquals(0,position(a.books.header)[0]);assertEquals(288,a.books.header.getWidth());for(String description:new String[]{"Pesquisar livros","Ordenar e filtrar","Opções dos livros"}){View button=f.description(a.books.header,description);Rect visible=new Rect();assertTrue(button.getGlobalVisibleRect(visible));assertEquals(44,visible.width());assertEquals(44,visible.height());}TextView title=(TextView)VoiceToolsTest.findText(a.books.header,"Todos os livros");assertNotNull(title);for(int i=0;i<title.getLayout().getLineCount();i++)assertEquals(0,title.getLayout().getEllipsisCount(i));f.capture(a.shell,"livros-estreito",288,640);}
 @Test public void returningToTheLibraryRestoresScrollWithoutMovingTheHeader()throws Exception{books(18);measure(360,800);a.books.scroll.scrollTo(0,430);a.tab="Início";a.render();f.drain();measure(360,800);a.tab="Livros";a.render();f.drain();measure(360,800);shadowOf(Looper.getMainLooper()).idle();assertEquals(430,a.books.scroll.getScrollY());assertEquals(0,position(a.books.header)[1]);}
 @Test public void headerUsesSmoothSeparatedCurvesAndBackgroundHasNoSecondHeader()throws Exception{Bitmap bitmap=Bitmap.createBitmap(360,110,Bitmap.Config.ARGB_8888);BrandSurface header=new BrandSurface(a,BrandSurface.HEADER);header.setBounds(0,0,360,110);header.draw(new Canvas(bitmap));int bg=AppPalette.of(a).bg,min=200,max=0;for(int x:new int[]{1,80,160,240,358}){int last=0;for(int y=0;y<110;y++)if(bitmap.getPixel(x,y)!=bg)last=y;min=Math.min(min,last);max=Math.max(max,last);assertEquals(255,Color.alpha(bitmap.getPixel(x,0)));}assertTrue("Curves must vary across width",max-min>=5);Bitmap page=Bitmap.createBitmap(360,800,Bitmap.Config.ARGB_8888);BrandSurface background=new BrandSurface(a,BrandSurface.BACKGROUND);background.setBounds(0,0,360,800);background.draw(new Canvas(page));assertEquals(bg,page.getPixel(10,100));bitmap.recycle();page.recycle();a.tab="Explorar";a.render();f.drain();f.capture(a.shell,"ondas-explorar",360,800);}
}
